"Вспомни, как жили древние люди.": "Remember how ancient people lived.",
"Вспомни, какой номер у какой службы.": "Remember which service has which number.",
"Вспомни, что нарисовано на флаге Казахстана, и ответь на вопросы.": "Remember what is drawn on the flag of Kazakhstan and answer the questions.",
"Вспомни, что ты узнал о царице Томирис.": "Remember what you learned about Queen Tomyris.",
