"Главная улица": "Main street",
"Главная улица и здания": "Main street and buildings",
"Главная улица — самая известная и оживлённая улица города или села. На ней много важных зданий.": "The main street is the most famous and busy street of a city or village. It has many important buildings.",
"Главный город страны называется столицей. Нажимай на картинки и узнавай о столице Казахстана.": "The main city of a country is called the capital. Tap the pictures and learn about the capital of Kazakhstan.",
