"День защитника": "Defender's Day",
"День рождения": "Birthday",
"Деньги Казахстана называются тенге. Мы платим ими, когда что-то покупаем.": "The money of Kazakhstan is called the tenge. We pay with it when we buy something.",
"Деньги Казахстана — тенге.": "The money of Kazakhstan is the tenge.",
"Деньги и магазин": "Money and shopping",
"Деревья живые, им больно. Беречь их нужно.": "Trees are alive and can be hurt. We must look after them.",
"Дети одних родителей — братья и сёстры. Старшие помогают младшим.": "Children of the same parents are brothers and sisters. The older ones help the younger ones.",
"Детская считалка": "A children's counting rhyme",
"Для бабушки я — ...": "For grandma I am ...",
"Для мамы и папы я — ...": "For mum and dad I am ...",
"Для родителей я сын или дочь. Для бабушки и дедушки — внук или внучка. Для брата или сестры — брат или сестра.": "For my parents I am a son or a daughter. For grandma and grandpa I am a grandson or granddaughter. For a brother or sister I am a brother or sister.",
"Для санок нужен снег — зимой.": "A sled needs snow, so it is for winter.",
"Для чего нужна письменность?": "What do we need writing for?",
"Добрые слова — тоже забота.": "Kind words are a kind of care too.",
"Дождаться зелёного света": "Wait for the green light",
"Дойти до перехода": "Walk to the crossing",
"Дом и квартира": "House and flat",
"Дом нужен всем людям.": "Every person needs a home.",
"Дом, машина и двор": "House, car and yard",
"Дома тоже бывает опасно. Нажимай на картинки и запоминай правила безопасного поведения.": "It can be dangerous at home too. Tap the pictures and remember the safety rules.",
"Дорога в школу должна быть безопасной. Ответь, как нужно идти.": "The way to school should be safe. Answer how to walk.",
"Дорога в школу и уроки": "The way to school and lessons",
"Дорогу переходят только по переходу и на зелёный свет.": "Cross the road only at a crossing and on the green light.",
"Дорожные знаки помогают водителям и пешеходам. Нажимай на знаки и читай, что они означают.": "Road signs help drivers and pedestrians. Tap the signs and read what they mean.",
"Достопримечательности": "Sights",
"Достопримечательности — интересные места": "Sights are interesting places",
"Достопримечательности — памятники, парки, музеи и другие известные места.": "Sights are monuments, parks, museums and other famous places.",
"Древнетюркские руны": "Old Turkic runes",
"Древние знаки": "Ancient signs",
"Древние люди высекали знаки на камне. Выбери цвет и нарисуй свои знаки на «камне» пальцем или мышкой.": "Ancient people carved signs on stone. Choose a colour and draw your own signs on the \"stone\" with your finger or mouse.",
"Древние люди охотились и собирали ягоды, корни и плоды, чтобы получить еду.": "Ancient people hunted and gathered berries, roots and fruits to get food.",
"Древние люди охотились на животных и собирали ягоды, корни и плоды.": "Ancient people hunted animals and gathered berries, roots and fruits.",
"Древние племена степей": "Ancient tribes of the steppes",
