"Древние тюрки писали рунами. Знаки высекали на камнях, и эти надписи сохранились до нашего времени.": "Ancient Turks wrote with runes. The signs were carved on stones, and these inscriptions have survived to our time.",
"Другой ребёнок моих родителей — девочка. Кто она мне?": "Another child of my parents is a girl. Who is she to me?",
"Другой ребёнок моих родителей — мальчик. Кто он мне?": "Another child of my parents is a boy. Who is he to me?",
