"Ездить верхом": "Ride a horse",
"Если заболел или ушибся, идёшь в медицинский кабинет. Там помогает медсестра.": "If you are ill or hurt, you go to the medical room. The nurse helps you there.",
"Если запахло дымом, нужно позвать взрослых и позвонить 101.": "If you smell smoke, call adults and dial 101.",
"Если стоять лицом к востоку, справа будет юг, а слева — север.": "If you stand facing east, south is on your right and north is on your left.",
"Есть нужно в одно и то же время, а еда должна быть полезной. Нажимай на картинки.": "You should eat at the same time every day, and the food should be healthy. Tap the pictures.",
