"Поздороваться с учителем. Хорошо?": "Greet the teacher. Is that good?",
"Пока не сюда. ": "Not here yet. ",
"Покупали в магазине": "Bought in a shop",
"Полезны овощи, фрукты, молоко, каша, мясо и рыба. Сладкого нужно понемногу.": "Vegetables, fruit, milk, porridge, meat and fish are healthy. Sweets only in small amounts.",
"Полярная звезда почти всегда стоит над севером.": "The Pole Star almost always stands over the north.",
"Помогает учителю следить за порядком": "Helps the teacher keep order",
"Помогать маме — это забота и уважение.": "Helping mum is care and respect.",
"Помочь бабушке донести сумку. Это забота о семье?": "Help grandma carry her bag. Is that caring for the family?",
"Помочь маме накрыть на стол. Это забота о семье?": "Help mum lay the table. Is that caring for the family?",
"Помочь однокласснику, если он упал. Правильно?": "Help a classmate if he falls. Is that right?",
"Пообедать, отдохнуть и сделать уроки": "Have lunch, rest and do homework",
"Порядок дома — это помощь всей семье.": "Order at home helps the whole family.",
"После завтрака школьник идёт на уроки.": "After breakfast a schoolchild goes to lessons.",
"После игры руки моют с мылом.": "After a game wash your hands with soap.",
"После школы нужно поесть, отдохнуть и выполнить домашнее задание.": "After school you need to eat, rest and do your homework.",
"Последняя проверка новых уроков": "A last check of the new lessons",
"Посмотреть налево и направо": "Look left and right",
"Посмотри на знак и выбери его название.": "Look at the sign and choose its name.",
"Посмотри на светофор и выбери": "Look at the traffic light and choose",
