"Правительство и главные учреждения": "The government and main institutions",
"Предлагает свой": "Offers their own",
"Представь, что у тебя в руке резец. Нарисуй палочками, уголками и зигзагами свои знаки на «камне».": "Imagine you hold a chisel. Draw your signs on the \"stone\" with sticks, corners and zigzags.",
"Привет! Это Барсик. Сегодня поговорим о безопасности. Светофор помогает переходить дорогу. Красный и жёлтый свет — стой. Зелёный — можно идти, но сначала посмотри по сторонам. Нажимай на цвета.": "Hi! This is Barsik. Today we will talk about safety. The traffic light helps you cross the road. Red and yellow mean stop. Green means you may go, but first look around. Tap the colours.",
"Приходить в школу вовремя. Правильно?": "Arrive at school on time. Is that right?",
"Про письменность": "About writing",
"Проводит урок": "Teaches the lesson",
"Прогулка ночью": "A walk at night",
"Продавец продаёт товары, а мы их покупаем.": "The seller sells goods, and we buy them.",
"Продаёт товары": "Sells goods",
