"дорога, знаки, службы спасения, флаг, времена года и дни недели.": "the road, signs, rescue services, the flag, the seasons and the days of the week.",
"завтрак, обед и ужин, в одно и то же время.": "breakfast, lunch and dinner, at the same time every day.",
