"каша, яйцо, бутерброд с молоком.": "porridge, an egg, a sandwich with milk.",
"мама, папа, дети, бабушка и дедушка. Они любят друг друга и заботятся друг о друге.": "mum, dad, children, grandma and grandpa. They love each other and take care of each other.",
