"нажимай на картинки, как идёт день.": "tap the pictures to see how the day goes.",
"памятники, парки, музеи, красивые здания. Их показывают гостям.": "monuments, parks, museums, beautiful buildings. They are shown to guests.",
"понедельник, вторник, среда, четверг, пятница, суббота и воскресенье. Суббота и воскресенье — выходные.": "Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday. Saturday and Sunday are days off.",
